1	using System.Globalization;
2	using System.Text.Json;
3	using System.Text.Json.Serialization;
4	using seed_b_backend.Api.Domain;
5	
6	namespace seed_b_backend.Api.Data;
7	
8	public static class SeedLoader
9	{
10	    public static async Task SeedAsync(AppDbContext db, string seedFilePath, CancellationToken cancellationToken = default)
11	    {
12	        var json = await File.ReadAllTextAsync(seedFilePath, cancellationToken);
13	        var seed = JsonSerializer.Deserialize<SeedFile>(json, JsonOptions)
14	            ?? throw new InvalidOperationException($"Seed-Datei '{seedFilePath}' konnte nicht gelesen werden.");
15	
16	        await using var transaction = await db.Database.BeginTransactionAsync(cancellationToken);
17	
18	        var propertyDefinitions = new Dictionary<(string SubcategoryId, string Name), PropertyDefinition>();
19	
20	        foreach (var kategorie in seed.Kategorien)
21	        {
22	            var category = new Category { Id = kategorie.Id, Name = kategorie.Name };
23	            db.Categories.Add(category);
24	
25	            foreach (var unterkategorie in kategorie.Unterkategorien)
26	            {
27	                var subcategory = new Subcategory
28	                {
29	                    Id = unterkategorie.Id,
30	                    Name = unterkategorie.Name,
31	                    Category = category
32	                };
33	                db.Subcategories.Add(subcategory);
34	
35	                foreach (var eigenschaftName in unterkategorie.Eigenschaften)
36	                {
37	                    if (propertyDefinitions.ContainsKey((unterkategorie.Id, eigenschaftName)))
38	                    {
39	                        continue;
40	                    }
41	
42	                    var propertyDefinition = new PropertyDefinition
43	                    {
44	                        Subcategory = subcategory,
45	                        Name = eigenschaftName
46	                    };
47	                    db.PropertyDefinitions.Add(propertyDefinition);
48	                    propertyDefinitions[(unterkategorie.Id, eigenschaftName)] = propertyDefinition;
49	                }
50	            }
51	        }
52	
53	        var suppliers = new Dictionary<string, Supplier>();
54	        foreach (var lieferant in seed.Lieferanten)
55	        {
56	            var supplier = new Supplier { Id = lieferant.Id, Name = lieferant.Name };
57	            db.Suppliers.Add(supplier);
58	            suppliers[lieferant.Id] = supplier;
59	        }
60	
61	        foreach (var produkt in seed.Produkte)
62	        {
63	            var product = new Product
64	            {
65	                Id = produkt.Id,
66	                Name = produkt.Name,
67	                Description = produkt.Beschreibung,
68	                SubcategoryId = produkt.UnterkategorieId
69	            };
70	            db.Products.Add(product);
71	
72	            foreach (var (eigenschaftName, wert) in produkt.Eigenschaften)
73	            {
74	                var canonicalValue = ToCanonicalValue(wert);
75	                if (canonicalValue is null)
76	                {
77	                    continue;
78	                }
79	
80	                if (!propertyDefinitions.TryGetValue((produkt.UnterkategorieId, eigenschaftName), out var propertyDefinition))
81	                {
82	                    throw new InvalidOperationException(
83	                        $"Seed-Datei ist inkonsistent: Produkt '{produkt.Id}' referenziert die Eigenschaft '{eigenschaftName}', die für Unterkategorie '{produkt.UnterkategorieId}' nicht definiert ist.");
84	                }
85	
86	                db.ProductProperties.Add(new ProductProperty
87	                {
88	                    Product = product,
89	                    PropertyDefinition = propertyDefinition,
90	                    Value = canonicalValue
91	                });
92	            }
